use lg_core::Money;
use lg_tax::{region, Line, RoundingScope};
use lg_tax::calc::breakdown;

#[test]
fn disc_l18() {
    let r = region("CA-QC").unwrap();
    let b = breakdown(&[Line::goods("g", Money::of(10000, "CAD"))], r, RoundingScope::PerLine).unwrap();
    assert_eq!(b.tax.minor(), 1498);
}
